-- EVT hook file for soccer_team_dock_menu (VRFW.host handlers, docs/internal/lua-hosts.md). Graft betterqol_team_name (betterqol_team_name_dock.lua). Generated by research/scripts/menu_assemble.py; do not edit by hand.
-- literal 12 (a one-call funcLuaCommand filter), and a name wider than the room is drawn in the next fit style.

BetterQoL = BetterQoL or {}
BetterQoL.team_name = BetterQoL.team_name or {}
local TN = BetterQoL.team_name

TN.STEM = "soccer_team_dock_menu"
TN.NAME_FRAME = 1922851874        -- team01_04_p1_team_name_frame
TN.NAME_TEXT = 1990181784
TN.KEYBOARD_OPEN = 962493425      -- the game's keyboard (keyboard_input_menu)
TN.KEYBOARD_TITLE = 1956827977
TN.LENGTH_ARG = 6                 -- the keyboard call's argument that holds the length
TN.TEXT_SIZE = 3549540977
TN.TEXT_STYLE = 2333948100        -- CMND_SET_TEXT_FONTSTYLE (layer, idx, node, style)
TN.SETTINGS = 3782444096
TN.RETAIL_LENGTH = 12

function TN.log(...)
  TN.logger = TN.logger or VRFW.logger.new("BetterQoL team_name")
  TN.logger(...)
end

-- Reads the settings once per menu VM.
function TN.settings()
  if TN.loaded then
    return
  end
  TN.loaded = true
  TN.length, TN.room, TN.baseStyle, TN.fitStyles = TN.RETAIL_LENGTH, nil, 0, {}
  local ok, length, room, base, list = pcall(funcLuaCommand, TN.SETTINGS)
  if not ok or type(length) ~= "number" then
    TN.log("no settings (BetterQoL's script did not answer): the game's length")
    return
  end
  TN.length = math.max(1, math.min(31, math.floor(length)))
  TN.room = type(room) == "number" and room or nil
  TN.baseStyle = type(base) == "number" and base or 0
  if type(list) == "string" then
    for key in string.gmatch(list, "%d+") do
      TN.fitStyles[#TN.fitStyles + 1] = tonumber(key)
    end
  end
  TN.log("length", TN.length, "room", TN.room, "fit styles", #TN.fitStyles)
end

-- Installs the filter on funcLuaCommand.
function TN.installFilter()
  if TN.base ~= nil or type(funcLuaCommand) ~= "function" then
    return
  end
  local base = funcLuaCommand
  TN.base = base
  funcLuaCommand = function(...)
    if TN.armed and (...) == TN.KEYBOARD_OPEN then
      local args = table.pack(...)
      if args[4] == TN.KEYBOARD_TITLE and type(args[TN.LENGTH_ARG]) == "number" then
        TN.armed = false
        TN.log("keyboard length", args[TN.LENGTH_ARG], "->", TN.length)
        args[TN.LENGTH_ARG] = TN.length
        return base(table.unpack(args, 1, args.n))
      end
    end
    return base(...)
  end
end

-- Returns the name's width in the node's current style.
local function width()
  local w = VRFW.host.menu_command(TN.TEXT_SIZE, TN.NAME_FRAME, 0, TN.NAME_TEXT)
  if type(w) == "number" and w > 0 then
    return w
  end
  return nil
end

-- the dock's own style first, then each fit style until the name fits the room (the last one stays)
function TN.fit()
  TN.settings()
  if TN.baseStyle == 0 or #TN.fitStyles == 0 then
    return
  end
  local room = TN.room
  if room == nil or room <= 0 then
    return
  end
  local open = VRFW.host.menu_command(1175615627 --[[CMND_GET_CREATE_LAYER_NUM]], TN.NAME_FRAME)
  if type(open) ~= "number" or open < 1 then
    return
  end
  VRFW.host.menu_command(TN.TEXT_STYLE, TN.NAME_FRAME, 0, TN.NAME_TEXT, TN.baseStyle)
  local w = width()
  if w == nil or w <= room then
    return
  end
  local first = w
  for i, style in ipairs(TN.fitStyles) do
    VRFW.host.menu_command(TN.TEXT_STYLE, TN.NAME_FRAME, 0, TN.NAME_TEXT, style)
    w = width()
    if w == nil or w <= room or i == #TN.fitStyles then
      TN.log("name width", first, "room", room, "-> fit style", i, "width", w)
      return
    end
  end
end

local host = VRFW.host
if type(host) == "table" and type(host.on) == "function" then
  host.on(TN.STEM, "OnEnter", {id = "BetterQoL.team_name.length", phase = "around", fn = function(nxt, a1, ...)
    if a1 ~= TN.NAME_FRAME then
      return nxt(a1, ...)
    end
    TN.settings()
    TN.installFilter()
    TN.armed = TN.length ~= TN.RETAIL_LENGTH
    local r = table.pack(nxt(a1, ...))
    TN.armed = false
    pcall(TN.fit)
    return table.unpack(r, 1, r.n)
  end})
  host.on(TN.STEM, "SetupTeamDockTeamName", {id = "BetterQoL.team_name.fit", phase = "after", fn = function()
    TN.fit()
  end})
end
